bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const e=process.env,chat=-1002373696859,messageId=4663,productId='sp_76f23430d1c29ca355960a95';
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:5000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
const base='https://api.telegram.org/bot'+token+'/';
async function call(method,params){
 const resp=await outgoing.fetch(base+method,{method:'POST',headers:{'content-type':'application/json'},
   body:JSON.stringify(params),signal:AbortSignal.timeout(20000),redirect:'error'});
 let data;
 try{data=await resp.json();}catch{throw Error('STK_IMAGE_TELEGRAM_RESPONSE_UNREADABLE');}
 const description=String(data?.description??'').toLowerCase();
 if(resp.status===200&&data?.ok===true){
  if(method==='getMe')return {state:'PASS',result:data.result};
  if(data.result===true||data.result?.message_id===messageId)return {state:'PASS'};
  throw Error('STK_IMAGE_RESPONSE_UNEXPECTED');
 }
 if(resp.status===400&&description.includes('message is not modified'))return {state:'NO_CHANGE'};
 const cat=description.includes('can\'t be edited')||description.includes('cannot be edited')||
    description.includes('message to edit not found')||description.includes('message to be edited not found')
    ?'EDIT_FORBIDDEN_OR_MISSING':
    description.includes('message not found')?'MESSAGE_MISSING':
    'OTHER_TELEGRAM_REJECTION';
 return {state:'REJECTED',code:resp.status,category:cat};
}
try{
 const q=await pool.query("SELECT p.title,p.status AS product_status,p.price_stars,t.status AS post_status,t.chat_id,t.message_thread_id,t.telegram_message_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[productId]);
 if(q.rowCount!==1||q.rows[0].product_status!=='published'||q.rows[0].price_stars!==50||
 Number(q.rows[0].chat_id)!==chat||Number(q.rows[0].message_thread_id)!==4640||
 Number(q.rows[0].telegram_message_id)!==messageId||
 !['sent','needs_reconcile'].includes(q.rows[0].post_status))throw Error('STK_IMAGE_EDIT_TARGET_MISMATCH');
 const me=await call('getMe',{});
 if(me.state!=='PASS'||String(me.result?.username).toLowerCase()!=='createvdobot'||me.result?.is_bot!==true)
  throw Error('STK_IMAGE_BOT_IDENTITY_WRONG');
 const title=String(q.rows[0].title),caption='🎨 '+title;
 if(caption.length>90)throw Error('STK_IMAGE_CAPTION_LONG');
 const one=await call('editMessageCaption',{chat_id:chat,message_id:messageId,caption});
 console.log('STK_IMAGE_CAPTION_EDIT_STATE='+one.state);
 if(one.category)console.log('STK_IMAGE_CAPTION_ERROR='+one.category);
 const two=await call('editMessageReplyMarkup',{chat_id:chat,message_id:messageId});
 console.log('STK_IMAGE_MARKUP_EDIT_STATE='+two.state);
 if(two.category)console.log('STK_IMAGE_MARKUP_ERROR='+two.category);
 if(['PASS','NO_CHANGE'].includes(one.state)&&['PASS','NO_CHANGE'].includes(two.state)){
  const save=await pool.query("UPDATE videobot_sticker_topic_posts SET status='sent',display_text=$1 WHERE product_id=$2 AND telegram_message_id=$3 AND status IN ('sent','needs_reconcile') RETURNING telegram_message_id",[caption,productId,messageId]);
  if(save.rowCount!==1)throw Error('STK_IMAGE_CAPTION_DB_NOT_RECONCILED');
  console.log('STK_NATIVE_IMAGE_ONLY_RECONCILED=PASS');
 }else{
  console.log('STK_NATIVE_IMAGE_ONLY_RECONCILED=BLOCKED');
 }
}finally{await outgoing.close();await pool.end();}
NODE
